package org.sleepwell.app;
import android.os.*;import android.view.*;import android.widget.*;import java.util.concurrent.*;
/** Default-off phone heuristics; saving never starts capture or changes an admitted night. */
public final class AwakeSettingsActivity extends androidx.activity.ComponentActivity {
 static final class Job {final AwakeSettings.Port port;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());AwakeSettingsActivity owner;boolean busy,saved,closed;String error="";Job(AwakeSettings.Port p){port=p;}void save(AwakePolicy policy){if(busy)return;busy=true;saved=false;error="";draw();worker.execute(()->{String failure="";try{port.save(policy.encode());}catch(RuntimeException bad){failure="Awake settings could not be saved. Try again.";}String result=failure;main.post(()->{busy=false;saved=result.isEmpty();error=result;draw();});});}void draw(){if(owner!=null&&!closed)owner.render();}}
 private AwakePolicy draft=AwakePolicy.OFF;private Job job;private String readError="";
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);Object old=getLastCustomNonConfigurationInstance();AwakeSettings.Factory settings=AwakeSettings.factory;try{job=old instanceof Job?(Job)old:new Job(settings.open(getApplicationContext()));String raw=job.port.read();draft=raw==null?AwakePolicy.OFF:AwakePolicy.decode(raw);}catch(RuntimeException bad){readError="Saved settings unavailable. Review and save to reset.";if(job==null)job=new Job(new AwakeSettings.Port(){public String read(){throw new IllegalStateException();}public void save(String value){settings.open(getApplicationContext()).save(value);}});}if(state!=null){readError=state.getString("error",readError);try{draft=AwakePolicy.decode(state.getString("draft"));}catch(RuntimeException bad){draft=AwakePolicy.OFF;}}job.owner=this;render();}
 @Override public Object onRetainCustomNonConfigurationInstance(){return job;}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("draft",draft.encode());state.putString("error",readError);}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Awake estimates",this::finish);Design.space(body,14);Design.text(body,"Optional phone clues that reduce estimated sleep time. Applies next recording.",14,400,Design.MUTED);Design.space(body,14);toggle(body,"Estimate awake time",draft.enabled,v->draft=new AwakePolicy(v,draft.interaction,draft.light,draft.snooze));Design.line(body);toggle(body,"Phone use",draft.interaction,v->draft=new AwakePolicy(draft.enabled,v,draft.light,draft.snooze));Design.text(body,"Unlock or explicit use; up to 30 sec after the last interaction. Screen-on alone is ignored.",12,400,Design.MUTED);Design.space(body,12);toggle(body,"Room light",draft.light,v->draft=new AwakePolicy(draft.enabled,draft.interaction,v,draft.snooze));Design.text(body,"At least 60 lux for 10 sec, using already-enabled light recording. Missing or stale samples are ignored.",12,400,Design.MUTED);Design.space(body,12);toggle(body,"Alarm snooze",draft.snooze,v->draft=new AwakePolicy(draft.enabled,draft.interaction,draft.light,v));Design.text(body,"Only successful snoozes while recording; stops at a pause or recording end.",12,400,Design.MUTED);Design.space(body,18);Design.text(body,"Heuristics, not validated sleep stages. Review or ignore estimates in each sleep report.",13,500,Design.BROWN);LinearLayout footer=RecordUi.footer(body);String status=!job.error.isEmpty()?job.error:job.saved?"Saved for the next recording.":readError;if(!status.isEmpty())Design.text(footer,status,13,500,Design.MUTED);View save=Design.button(footer,job.busy?"Saving…":"Save awake settings",true,()->job.save(draft));RecordUi.enabled(save,!job.busy);}
 private void toggle(LinearLayout body,String label,boolean value,java.util.function.Consumer<Boolean> change){View control=Design.toggle(body,label,null,value,v->{try{change.accept(v);readError="";}catch(IllegalArgumentException invalid){readError=invalid.getMessage();}render();});RecordUi.enabled(control,!job.busy);}
 @Override protected void onDestroy(){if(job.owner==this)job.owner=null;if(!isChangingConfigurations()){job.closed=true;job.worker.shutdown();}super.onDestroy();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
